def test_load_json_imageinline():
    json_data = r"""
    {
      "kind": "image",
      "src": "sample",
      "alt": "sample",
      "title": "sample"
    }
    """
    data = json.loads(json_data, strict=False)
    instance = ImageInline.load(data)
    assert instance is not None
    assert instance.kind == "image"
    assert instance.src == "sample"
    assert instance.alt == "sample"
    assert instance.title == "sample"


