def test_roundtrip_json_imageinline():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "kind": "image",
      "src": "sample",
      "alt": "sample",
      "title": "sample"
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = ImageInline.load(original_data)
    saved_data = instance.save()
    reloaded = ImageInline.load(saved_data)
    assert reloaded is not None
    assert reloaded.kind == "image"
    assert reloaded.src == "sample"
    assert reloaded.alt == "sample"
    assert reloaded.title == "sample"


